def _correlation_window_region(
    values_x: list,
    status_x: list,
    uncertainty_x: list,
    values_y: list,
    status_y: list,
    uncertainty_y: list,
    cells: list[tuple[int, int]],
    t_start: int,
    t_end: int,
    min_count: int,
) -> dict:
    paired_vx: list[float] = []
    paired_vy: list[float] = []
    paired_ux: list[float] = []
    paired_uy: list[float] = []
    for t in range(t_start, t_end + 1):
        for i, j in cells:
            if status_x[t][i][j] != "missing" and status_y[t][i][j] != "missing":
                paired_vx.append(values_x[t][i][j])
                paired_vy.append(values_y[t][i][j])
                paired_ux.append(uncertainty_x[t][i][j])
                paired_uy.append(uncertainty_y[t][i][j])

    count = len(paired_vx)
    if count < min_count:
        return {
            "count": count,
            "covariance": None,
            "correlation": None,
            "uncertainty": None,
        }

    mean_x = sum(paired_vx) / count
    mean_y = sum(paired_vy) / count
    covariance = (
        sum((vx - mean_x) * (vy - mean_y) for vx, vy in zip(paired_vx, paired_vy))
        / count
    )
    variance_x = sum((vx - mean_x) ** 2 for vx in paired_vx) / count
    variance_y = sum((vy - mean_y) ** 2 for vy in paired_vy) / count
    if variance_x == 0.0 or variance_y == 0.0:
        correlation = None
    else:
        correlation = covariance / math.sqrt(variance_x * variance_y)
    uncertainty = math.sqrt(
        sum(ux ** 2 + uy ** 2 for ux, uy in zip(paired_ux, paired_uy))
    ) / count

    return {
        "count": count,
        "covariance": _round_output(covariance),
        "correlation": (
            None if correlation is None else _round_output(correlation)
        ),
        "uncertainty": _round_output(uncertainty),
    }


def _autocorrelation_window_region(
    values: list,
    status: list,
    uncertainty: list,
    cells: list[tuple[int, int]],
    t_start: int,
    t_end: int,
    min_count: int,
) -> dict:
    paired_x: list[float] = []
    paired_y: list[float] = []
    uncertainty_sq_sum = 0.0
    for t in range(t_start, t_end):
        for i, j in cells:
            if status[t][i][j] != "missing" and status[t + 1][i][j] != "missing":
                paired_x.append(values[t][i][j])
                paired_y.append(values[t + 1][i][j])
                uncertainty_sq_sum += (
                    uncertainty[t][i][j] ** 2 + uncertainty[t + 1][i][j] ** 2
                )

    count = len(paired_x)
    if count < min_count:
        return {
            "count": count,
            "correlation": None,
            "uncertainty": None,
        }

    mean_x = sum(paired_x) / count
    mean_y = sum(paired_y) / count
    covariance = (
        sum((x - mean_x) * (y - mean_y) for x, y in zip(paired_x, paired_y))
        / count
    )
    variance_x = sum((x - mean_x) ** 2 for x in paired_x) / count
    variance_y = sum((y - mean_y) ** 2 for y in paired_y) / count
    if variance_x == 0.0 or variance_y == 0.0:
        correlation = None
    else:
        correlation = covariance / math.sqrt(variance_x * variance_y)
    aggregated_uncertainty = math.sqrt(uncertainty_sq_sum) / count

    return {
        "count": count,
        "correlation": (
            None if correlation is None else _round_output(correlation)
        ),
        "uncertainty": _round_output(aggregated_uncertainty),
    }


